  "math-8c": {
    units: { a: "Circular functions: graphs, transformations and models" },
    paper: "P1",
    qs: [
      { id: "math-8-d44", u: "a", s: "A", m: "1+1+2", paper: "P2", html: true, t: "Let \\(f(x) = 3\\sin (2x) + 1\\).<br>(a) Write down the amplitude of \\(f\\).<br>(b) Find the period of \\(f\\).<br>(c) Write down the range of \\(f\\).",
        rule: "(a) A1. (b) A1. (c) A1 each end.",
        pts: ["(a) 3 (A1) [1]", "(b) \\(\\frac{2\\pi}{2} = \\pi\\) (A1) [1]", "(c) minimum \\(-2\\) (A1) [1]", "\\(-2 \\le f(x) \\le 4\\) (A1) [1]"] },
      { id: "math-8-d45", u: "a", s: "A", m: "1+2+3", paper: "P2", html: true, t: "The depth of water in a harbour, \\(d\\) metres, \\(t\\) hours after midnight is \\(d(t) = 5 + 2.5\\cos \\left(\\frac{\\pi t}{6}\\right)\\).<br>(a) Write down the maximum depth.<br>(b) Find the period of \\(d\\).<br>(c) Find the first time after midnight when the depth is 6 m.",
        rule: "(a) A1. (b) M1 A1. (c) M1 equation, A1 \\(\\cos = 0.4\\), A1.",
        pts: ["(a) 7.5 m (A1) [1]", "(b) \\(\\frac{2\\pi}{\\pi/6}\\) (M1) [1]", "\\(= 12\\) hours (A1) [1]", "(c) \\(5 + 2.5\\cos \\left(\\frac{\\pi t}{6}\\right) = 6\\) (M1) [1]", "\\(\\cos \\left(\\frac{\\pi t}{6}\\right) = 0.4\\) (A1) [1]", "\\(t = 2.21\\) hours (about 02:13) (A1) [1]"] },
      { id: "math-8-d46", u: "a", s: "A", m: "4", paper: "P1", html: true, t: "The graph of \\(y = a\\cos (bx) + c\\), where \\(a, b > 0\\), has a maximum point at \\((0, 7)\\) and the next minimum point at \\(\\left(\\frac{\\pi}{2}, 1\\right)\\). Find the values of \\(a\\), \\(b\\) and \\(c\\).",
        rule: "A1 \\(a\\), A1 \\(c\\), M1 period \\(\\pi\\), A1 \\(b\\).",
        pts: ["\\(a = \\frac{7 - 1}{2} = 3\\) (A1) [1]", "\\(c = \\frac{7 + 1}{2} = 4\\) (A1) [1]", "period \\(= 2\\times\\frac{\\pi}{2} = \\pi\\) (M1) [1]", "\\(b = \\frac{2\\pi}{\\pi} = 2\\) (A1) [1]"] },
      { id: "math-8-d47", u: "a", s: "A", m: "1+2+3", paper: "P2", html: true, t: "The height, \\(h\\) metres, of a seat on a Ferris wheel \\(t\\) seconds after the start is \\(h(t) = 22 - 20\\cos \\left(\\frac{\\pi t}{15}\\right)\\).<br>(a) Write down the maximum height of the seat.<br>(b) Find the time taken for one complete revolution.<br>(c) Find the length of time during one revolution for which the seat is more than 30 m above the ground.",
        rule: "(a) A1. (b) M1 A1. (c) M1 equation/inequality (GDC), A1 both times, A1.",
        pts: ["(a) 42 m (A1) [1]", "(b) \\(\\frac{2\\pi}{\\pi/15}\\) (M1) [1]", "\\(= 30\\) seconds (A1) [1]", "(c) \\(22 - 20\\cos \\left(\\frac{\\pi t}{15}\\right) > 30\\) (M1) [1]", "\\(t = 9.46\\) and \\(t = 20.5\\) (A1) [1]", "\\(20.54 - 9.46 = 11.1\\) seconds (A1) [1]"] },
      { id: "math-8-d48", u: "a", s: "A", m: "1+1+2", paper: "P2", html: true, t: "(a) Write down the period of \\(y = \\tan (3x)\\).<br>(b) Write down the period of \\(y = 2\\sin \\left(\\frac{x}{2}\\right)\\).<br>(c) Find the range of \\(y = 5 - 2\\cos x\\).",
        rule: "(a) A1. (b) A1. (c) A1 A1.",
        pts: ["(a) \\(\\frac{\\pi}{3}\\) (A1) [1]", "(b) \\(4\\pi\\) (A1) [1]", "(c) minimum \\(5 - 2 = 3\\), maximum \\(5 + 2 = 7\\) (A1) [1]", "\\(3 \\le y \\le 7\\) (A1) [1]"] },
      { id: "math-8-d54", u: "a", s: "C", m: "2+2+2+2+4+1", paper: "P2", html: true, t: "The temperature, \\(T\\) °C, in a city \\(t\\) hours after midnight is modelled by \\(T(t) = a\\sin (b(t - c)) + d\\), where \\(a, b > 0\\) and \\(0 \\le c < 24\\). The maximum temperature of 28 °C occurs at \\(t = 15\\) and the minimum of 12 °C occurs at \\(t = 3\\). The period is 24 hours.<br>(a) Find the values of \\(a\\) and \\(d\\).<br>(b) Find the value of \\(b\\).<br>(c) Show that \\(c = 9\\).<br>(d) Find the temperature at 10:00.<br>(e) Find the length of time during the day for which the temperature is above 25 °C.<br>(f) Write down the first time after midnight at which the temperature is 20 °C and rising.",
        rule: "(a) A1 A1. (b) M1 A1. (c) M1 maximum when \\(b(t - c) = \\frac{\\pi}{2}\\), A1 AG. (d) M1 A1. (e) M1 inequality, A1 A1 boundary times, A1 duration. (f) A1.",
        pts: ["(a) \\(a = \\frac{28 - 12}{2} = 8\\) (A1) [1]", "\\(d = \\frac{28 + 12}{2} = 20\\) (A1) [1]", "(b) \\(b = \\frac{2\\pi}{24}\\) (M1) [1]", "\\(b = \\frac{\\pi}{12} = 0.262\\) (A1) [1]", "(c) \\(\\frac{\\pi}{12}(15 - c) = \\frac{\\pi}{2}\\) (M1) [1]", "\\(15 - c = 6 \\Rightarrow c = 9\\) (AG) [1]", "(d) \\(8\\sin \\left(\\frac{\\pi}{12}(10 - 9)\\right) + 20\\) (M1) [1]", "\\(= 22.1\\) °C (A1) [1]", "(e) \\(8\\sin \\left(\\frac{\\pi}{12}(t - 9)\\right) + 20 > 25\\) (M1) [1]", "\\(t = 11.58\\) (A1) [1]", "\\(t = 18.42\\) (A1) [1]", "duration \\(= 6.84\\) hours (A1) [1]", "(f) \\(t = 9\\) (09:00) (A1) [1]"] },
      { id: "math-8-d55", u: "a", s: "C", m: "1+2+2+4+3+2", paper: "P1", html: true, t: "Let \\(f(x) = 4\\sin x\\cos x + 1\\).<br>(a) Show that \\(f(x) = 2\\sin 2x + 1\\).<br>(b) Write down the amplitude and the period of \\(f\\).<br>(c) Write down the range of \\(f\\).<br>(d) Solve \\(f(x) = 2\\), for \\(0 \\le x \\le \\pi\\).<br>The graph of \\(f\\) is translated by \\(\\binom{\\pi/4}{0}\\) to give the graph of \\(g\\).<br>(e) Show that \\(g(x) = 1 - 2\\cos 2x\\).<br>(f) Find the maximum value of \\(g\\) and the smallest positive value of \\(x\\) at which it occurs.",
        rule: "(a) A1 AG. (b) A1 A1. (c) A1 A1. (d) M1 \\(\\sin 2x = \\frac{1}{2}\\), M1 second value of \\(2x\\), A1 A1. (e) M1 \\(f(x - \\frac{\\pi}{4})\\), A1 \\(\\sin (2x - \\frac{\\pi}{2})\\), A1 AG. (f) A1 A1.",
        pts: ["(a) \\(4\\sin x\\cos x = 2(2\\sin x\\cos x) = 2\\sin 2x\\), so \\(f(x) = 2\\sin 2x + 1\\) (AG) [1]", "(b) amplitude 2 (A1) [1]", "period \\(\\pi\\) (A1) [1]", "(c) minimum \\(-1\\), maximum 3 (A1) [1]", "\\(-1 \\le f(x) \\le 3\\) (A1) [1]", "(d) \\(\\sin 2x = \\frac{1}{2}\\) (M1) [1]", "\\(2x = \\frac{\\pi}{6},\\ \\frac{5\\pi}{6}\\) (M1) [1]", "\\(x = \\frac{\\pi}{12}\\) (A1) [1]", "\\(x = \\frac{5\\pi}{12}\\) (A1) [1]", "(e) \\(g(x) = f\\left(x - \\frac{\\pi}{4}\\right) = 2\\sin \\left(2x - \\frac{\\pi}{2}\\right) + 1\\) (M1) [1]", "\\(\\sin \\left(2x - \\frac{\\pi}{2}\\right) = -\\cos 2x\\) (A1) [1]", "\\(g(x) = 1 - 2\\cos 2x\\) (AG) [1]", "(f) maximum value 3 (A1) [1]", "when \\(\\cos 2x = -1\\), \\(x = \\frac{\\pi}{2}\\) (A1) [1]"] },
    ],
  },
